import { Navigate } from 'react-router-dom';
import s from './Dialogs.module.css'
import DialogItem from './DialogsItem/DialogsItem.jsx'
import Message from './Message/Message.jsx'
import MessageReduxForm from './AddMessageForm.jsx';

const Dialogs = (props) => {
    let dialogsElements = props.dialogsData.map( d => <DialogItem name={d.name} id={d.id} key={d.id}/>);
    let messagesElements = props.messagesData.map( m => <Message message={m.message} key={m.id}/>);
    
    let addNewMessage = (values) => {
        props.sendMessage(values.newMessageBody)
    }

    if(!props.isAuth) {
        return <Navigate to='/login' />
    }
    return (
        <div className={s.dialogs}>
            <div className={s.dialogs__items}>
                {dialogsElements}
            </div>
            <div className={s.messages}>
                <div>
                    {messagesElements}
                </div>
                <div>
                    <MessageReduxForm onSubmit={addNewMessage}/>
                </div>
            </div>
        </div>
    )
}

export default Dialogs